prompt --application/shared_components/security/authorizations/auth_is_tournament_admin
begin
wwv_flow_imp_shared.create_security_scheme(
 p_id=>wwv_flow_imp.id(13068153277230616)
,p_name=>'AUTH_IS_TOURNAMENT_ADMIN'
,p_static_id=>'auth-is-tournament-admin'
,p_scheme_type=>'NATIVE_FUNCTION_BODY'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'plsql_function_body', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '  l_is_admin party_member.is_admin%TYPE;',
    'BEGIN',
    '  SELECT pm.is_admin',
    '  INTO   l_is_admin',
    '  FROM   party_member pm',
    '  JOIN   party p     ON p.id = pm.party_id',
    '  JOIN   app_user au ON au.id = pm.user_id',
    '  WHERE  p.tournament_id = :AI_TOURNAMENT_ID',
    '  AND    LOWER(au.google_email) = LOWER(:APP_USER)',
    '  AND    pm.is_admin = TRUE',
    '  AND    ROWNUM = 1;',
    '',
    '  RETURN l_is_admin;',
    'EXCEPTION',
    '  WHEN NO_DATA_FOUND THEN',
    '    RETURN FALSE;',
    'END;')))).to_clob
,p_version_scn=>'46971759858455'
,p_caching=>'BY_USER_BY_SESSION'
,p_created_on=>wwv_flow_imp.dz('20260704100012Z')
,p_updated_on=>wwv_flow_imp.dz('20260704103404Z')
,p_created_by=>'LAB'
,p_updated_by=>'LAB'
);
end;
