prompt --application/shared_components/logic/application_computations/ai_party_id
begin
wwv_flow_imp_shared.create_flow_computation(
 p_id=>wwv_flow_imp.id(11420874976378236)
,p_computation_sequence=>10
,p_computation_item=>'AI_PARTY_ID'
,p_static_id=>'ai-party-id'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
,p_computation_processed=>'REPLACE_EXISTING'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT CASE ',
'    WHEN :P0_PARTY_TOURNAMENT IS NOT NULL ',
'    THEN TO_NUMBER(SUBSTR(:P0_PARTY_TOURNAMENT, 1, INSTR(:P0_PARTY_TOURNAMENT, ''_'') - 1))',
'    ELSE (',
'        SELECT MIN(p.id)',
'        FROM   TIPOVACKA.PARTY p',
'        JOIN   TIPOVACKA.PARTY_MEMBER pm ON pm.PARTY_ID = p.ID',
'        JOIN   TIPOVACKA.TOURNAMENT   t  ON t.ID = p.TOURNAMENT_ID',
'        JOIN   TIPOVACKA.APP_USER     u  ON u.ID = pm.USER_ID',
'        WHERE  u.GOOGLE_EMAIL = :APP_USER',
'          AND  t.IS_ACTIVE = 1',
'    )',
'END',
'FROM DUAL'))
,p_version_scn=>'46967156363751'
,p_created_on=>wwv_flow_imp.dz('20260608081013Z')
,p_updated_on=>wwv_flow_imp.dz('20260609082610Z')
,p_created_by=>'LAB'
,p_updated_by=>'LAB'
);
end;
