,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT RANK',
'     , MEDAL',
'     , AVATAR_URL',
'     , FULL_NAME as NAME',
'     , TOTAL_POINTS',
'     , GAMES_TIPPED',
'     , EXACT_HITS',
'     , WINNER_HITS',
'     , WRONG_HITS',
'  FROM TIPOVACKA.V_LEADERBOARD',
' WHERE PARTY_ID = :AI_PARTY_ID ',
'   AND TOURNAMENT_ID = :AI_TOURNAMENT_ID',
' ORDER BY RANK ASC, EXACT_HITS DESC, WINNER_HITS DESC, WRONG_HITS ASC, GAMES_TIPPED DESC',
'',
' /*',
'',
'select * from (',
'SELECT -- RANK',
'      rank() over (order by case when full_name = ''Miro'' then 60 + TOTAL_POINTS else total_points end desc) as rank',
'     ,   CASE rank() over (order by case when full_name = ''Miro'' then 60 + TOTAL_POINTS else total_points end desc)',
unistr('        WHEN 1 THEN ''\D83E\DD47'' '),
unistr('        WHEN 2 THEN ''\D83E\DD48'' '),
unistr('        WHEN 3 THEN ''\D83E\DD49'' '),
unistr('        WHEN 4 THEN ''\D83E\DD54'' '),
unistr('        WHEN 5 THEN ''\D83C\DF7F'' '),
unistr('        WHEN 6 THEN ''\D83D\DE48'' '),
unistr('        WHEN 7 THEN ''\D83D\DC22'' '),
'    END AS MEDAL',
'     , AVATAR_URL',
'     , FULL_NAME as NAME',
'     , case when full_name = ''Miro'' then 60 + TOTAL_POINTS else total_points end as  total_points',
'     , GAMES_TIPPED',
'     , EXACT_HITS',
'     , WINNER_HITS',
'     , WRONG_HITS',
'     , case when FULL_NAME = ''Miro'' then 20 else 0 end as APP_CREATING',
'     , case when FULL_NAME = ''Miro'' then 20 else 0 end as MOST_UPDATED_RESULTS',
'     , case when FULL_NAME = ''Miro'' then 20 else 0 end as MOST_INSERTED_MATCHES',
'  FROM TIPOVACKA.V_LEADERBOARD',
' WHERE PARTY_ID = :AI_PARTY_ID ',
'   AND TOURNAMENT_ID = :AI_TOURNAMENT_ID',
'   )',
' ORDER BY RANK ASC, EXACT_HITS DESC, WINNER_HITS DESC, WRONG_HITS ASC, GAMES_TIPPED DESC',
'',
'',
'*/',
'',
';'))
