wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(9444409752953649)
,p_plug_name=>'Tipuj'
,p_static_id=>'tipuj'
,p_title=>' '
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2100526641005906379
,p_plug_display_sequence=>10
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT * FROM (',
'SELECT     g.id               AS game_id',
'  , g.game_date ',
'  , g.group_name',
'  , th.emoji_flag || '' '' || th.code || '' - '' || ta.code || '' '' || ta.emoji_flag as game_code',
unistr('  -- Pridan\00FD div s title a help kurzorom'),
'  , ''<div title="'' || th.name || '' - '' || ta.name || ''" style="white-space: normal; line-height: 1.4; cursor: help;">'' ||',
'    to_char( g.game_date, ''DD.MM HH24:MI'' ) || '' <br> '' || ',
'    th.emoji_flag || '' '' || th.code || '' - '' || ta.code || '' '' || ta.emoji_flag || ''</div>'' as game',
'  , th.NAME || '' - '' || ta.NAME as game_name',
'  , TH.NAME AS home_team',
'  , TA.NAME AS away_team',
'  , b.home_score       AS moj_tip_home',
'  , b.away_score       AS moj_tip_away',
'FROM GAME G ',
'LEFT JOIN TEAM TH',
'  ON G.HOME_TEAM_ID = TH.ID',
'LEFT JOIN TEAM TA',
'  ON G.AWAY_TEAM_ID = TA.ID',
'LEFT JOIN V_BET_LAST B ',
'  ON    G.ID = B.GAME_ID  ',
'    AND b.user_id = (SELECT u.id FROM TIPOVACKA.APP_USER u WHERE u.google_email = :APP_USER) ',
'WHERE  g.tournament_id = :AI_TOURNAMENT_ID',
'  AND  g.is_finished   = 0',
'  AND  g.is_locked     = 0',
'  AND  g.game_date >= CAST(SYSTIMESTAMP AT TIME ZONE ''Europe/Bratislava'' AS DATE)',
'ORDER BY g.game_date )',
';'))
,p_plug_source_type=>'NATIVE_IG'
,p_prn_units=>'INCHES'
,p_prn_paper_size=>'LETTER'
,p_prn_width=>11
,p_prn_height=>8.5
,p_prn_orientation=>'HORIZONTAL'
