wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(11669859192206522)
,p_process_sequence=>20
,p_process_point=>'ON_SUBMIT_BEFORE_COMPUTATION'
,p_region_id=>wwv_flow_imp.id(9444409752953649)
,p_process_type=>'NATIVE_IG_DML'
,p_process_name=>'insert tip'
,p_static_id=>'insert-tip'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'dml_plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    v_user_id   TIPOVACKA.APP_USER.ID%TYPE;',
    '    v_game_date DATE;',
    '    v_allow_draw TIPOVACKA.GAME.ALLOW_DRAW%TYPE;',
    'BEGIN',
    '    ',
    '    SELECT id INTO v_user_id ',
    '    FROM TIPOVACKA.APP_USER ',
    '    WHERE google_email = :APP_USER;',
    '',
    '    IF :APEX$ROW_STATUS IN (''C'', ''U'') THEN',
    '        ',
    '        IF :MOJ_TIP_HOME IS NOT NULL AND :MOJ_TIP_AWAY IS NOT NULL THEN',
    '            ',
    '            SELECT game_date, allow_draw INTO v_game_date, v_allow_draw',
    '            FROM TIPOVACKA.GAME ',
    '            WHERE id = :GAME_ID;',
    '            ',
    '            IF CAST(SYSTIMESTAMP AT TIME ZONE ''Europe/Bratislava'' AS DATE) > v_game_date THEN',
    unistr('                raise_application_error(-20001, ''Tip u\017E nie je mo\017En\00E9 ulo\017Ei\0165. Z\00E1pas sa u\017E za\010Dal!'');'),
    '            END IF;',
    '            ',
    '            IF v_allow_draw = 0 AND :MOJ_TIP_HOME = :MOJ_TIP_AWAY THEN',
    unistr('                raise_application_error(-20002, ''Rem\00EDza nie je povolen\00E1. Zadaj rozdielne sk\00F3re.'');'),
    '            END IF;',
    '            ',
    '            INSERT INTO TIPOVACKA.BET (',
    '                PARTY_ID, ',
    '                USER_ID, ',
    '                GAME_ID, ',
    '                HOME_SCORE, ',
    '                AWAY_SCORE,',
    '                CREATED_AT',
    '            )',
    '            VALUES (',
    '                :AI_PARTY_ID, ',
    '                v_user_id, ',
    '                :GAME_ID, ',
    '                :MOJ_TIP_HOME, ',
    '                :MOJ_TIP_AWAY,',
    '                CAST(SYSTIMESTAMP AT TIME ZONE ''Europe/Bratislava'' AS DATE)',
    '            );',
    '                ',
    '            COMMIT;',
    '            ',
    '        END IF;',
    '    END IF;',
    'END;')),
  'lock_row', 'N',
  'prevent_lost_updates', 'Y',
  'target_type', 'PLSQL_CODE')).to_clob
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>11669859192206522
,p_created_on=>wwv_flow_imp.dz('20260609183936Z')
,p_updated_on=>wwv_flow_imp.dz('20260628184151Z')
,p_created_by=>'LAB'
,p_updated_by=>'LAB'
);
end;
/
