    '',
    '    CASE :APEX$ROW_STATUS',
    '',
    '        WHEN ''U'' THEN',
    '',
    '            UPDATE TIPOVACKA.GAME',
    '',
    '               SET home_score = :HOME_SCORE,',
    '',
    '                   away_score = :AWAY_SCORE,',
    '',
    '                   updated_by = :APP_USER,',
    '',
    '                   is_locked = 1,',
    '',
    '                   is_finished = 1,',
    '',
    unistr('                   -- Ulo\017E\00ED presn\00FD bratislavsk\00FD \010Das skonvertovan\00FD na typ DATE:'),
    '',
    '                   updated_at = CAST(SYSTIMESTAMP AT TIME ZONE ''Europe/Bratislava'' AS DATE)',
    '',
    '             WHERE id         = :GAME_ID;',
    '',
    '    END CASE;',
    '',
    '    COMMIT ;',
    '',
    '    P_CALC_POINTS ;',
    '',
    'END;',
    '',
    '')),
  'lock_row', 'N',
  'prevent_lost_updates', 'Y',
  'target_type', 'PLSQL_CODE')).to_clob
