unistr('  \2022 AI_TOURNAMENT_ID: <span style="color: green;">&AI_TOURNAMENT_ID.</span> <br>'),
unistr('  \2022 Aktu\00E1lny pou\017E\00EDvate\013E (:APP_USER): <span style="color: blue;">&APP_USER.</span>'),
'</div>',
'',
'<br>',
'',
'<div style="padding: 10px; background-color: #f4f4f4; border: 1px solid #ccc;">',
unistr('  <strong>[VYGENEROVAN\00DD SQL DOPYT]</strong>'),
'  <pre style="white-space: pre-wrap; margin-top: 5px; color: #333;">',
'&F_BET_PIVOT(&AI_PARTY_ID.,&AI_TOURNAMENT_ID.).',
'  </pre>',
'</div>'))
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
