wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(11881920136689737)
,p_plug_name=>'debug plsql'
,p_static_id=>'debug-plsql'
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_plug_template=>4072358936313175081
,p_plug_display_sequence=>40
,p_plug_new_grid_row=>false
,p_plug_new_grid_column=>false
,p_plug_item_display_point=>'ABOVE'
,p_location=>null
,p_function_body_language=>'PLSQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_party_id      NUMBER := TO_NUMBER(:AI_PARTY_ID);',
'    v_tournament_id NUMBER := TO_NUMBER(:AI_TOURNAMENT_ID);',
'    v_app_user      VARCHAR2(255) := :APP_USER;',
'    ',
unistr('    v_party_name      VARCHAR2(255) := ''Nen\00E1jden\00E9 / NULL'';'),
unistr('    v_tournament_name VARCHAR2(255) := ''Nen\00E1jden\00E9 / NULL'';'),
'    v_vystup          CLOB;',
'BEGIN',
unistr('    -- Vytiahnutie n\00E1zvu Party'),
'    IF v_party_id IS NOT NULL THEN',
'        BEGIN',
'            SELECT name INTO v_party_name ',
'            FROM TIPOVACKA.PARTY ',
'            WHERE id = v_party_id;',
'        EXCEPTION WHEN OTHERS THEN v_party_name := ''Chyba: '' || SQLERRM;',
'        END;',
'    END IF;',
'',
unistr('    -- Vytiahnutie n\00E1zvu Turnaja'),
'    IF v_tournament_id IS NOT NULL THEN',
'        BEGIN',
'            SELECT name INTO v_tournament_name ',
'            FROM TIPOVACKA.TOURNAMENT ',
'            WHERE id = v_tournament_id;',
'        EXCEPTION WHEN OTHERS THEN v_tournament_name := ''Chyba: '' || SQLERRM;',
'        END;',
'    END IF;',
'',
unistr('    -- Skladanie v\00FDsledn\00E9ho textu do premennej'),
'    v_vystup := ''<div style="font-family: monospace; padding: 15px; background: #fdfdfd; border: 1px solid #ddd; line-height: 1.6;">''',
'             || ''<strong>[APEX PL/SQL DEBUG DATA]</strong><br>''',
'             || ''-----------------------------------------<br>''',
unistr('             || ''\2022 <strong>PARTY_ID:</strong> '' || NVL(TO_CHAR(v_party_id), ''NULL'') || ''<br>'''),
unistr('             || ''\2022 <strong>PARTY_NAME:</strong> '' || v_party_name || ''<br>'''),
unistr('             || ''\2022 <strong>TOURNAMENT_ID:</strong> '' || NVL(TO_CHAR(v_tournament_id), ''NULL'') || ''<br>'''),
unistr('             || ''\2022 <strong>TOURNAMENT_NAME:</strong> '' || v_tournament_name || ''<br>'''),
unistr('             || ''\2022 <strong>APP_USER:</strong> '' || NVL(v_app_user, ''NULL'') || ''<br>'''),
'             || ''-----------------------------------------<br>''',
'             || ''</div>'';',
'',
unistr('    -- \D83C\DF1F K\013D\00DA\010COV\00C1 OPRAVA: Vr\00E1tenie hodnoty, ktor\00FA APEX o\010Dak\00E1va'),
'    RETURN v_vystup;',
'END;'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_DYNAMIC_CONTENT'
,p_created_on=>wwv_flow_imp.dz('20260611155310Z')
,p_updated_on=>wwv_flow_imp.dz('20260611170944Z')
,p_created_by=>'LAB'
,p_updated_by=>'LAB'
);
